CREATE OR REPLACE SECURE VIEW DP_NERC.OUT_DATA_SUBMISSION
  WITH TAG (GOV.DATA_CLASSIFICATION = 'Internal - Restricted', GOV.DATA_OWNER = 'Energy Data Engineering Team', GOV.DOMAIN = 'Energy_Compliance_Package')
  COMMENT = 'Atomic contracted output for DataSubmission'
AS
SELECT f.DATA_SUBMISSION_ID, f.DATE_KEY, f.FILING_PERIOD, f.REPORTING_ENTITY, f.STATUS, f.SUBMISSION_TYPE, f.SUBMITTED_BY, d2.FISCAL_YEAR, d2.FULL_DATE, d2.IS_HOLIDAY, d2.IS_WEEKEND, d2.MONTH_NAME, d2.MONTH_NUMBER, d2.QUARTER
FROM CORE.FCT_DATA_SUBMISSION f
LEFT JOIN CORE.DIM_REPORTING_ENTITY d1 ON f.REPORTING_ENTITY = d1.REPORTING_ENTITY
LEFT JOIN CORE.DIM_DATE d2 ON f.DATE_KEY = d2.DATE_KEY;
